('Cível','Embargos de terceiro fundados em posse advinda de compromisso de compra e venda sem registro','súmula','STJ, Corte Especial, sessão de 18/06/1993, DJ 02/07/1993, p. 13.283','Súmula 84/STJ','',
$$[{"tese_assunto":"Embargos de terceiro e compromisso de compra e venda sem registro","ratio_decidendi":"É admissível a oposição de embargos de terceiro fundados em alegação de posse advinda do compromisso de compra e venda de imóvel, ainda que desprovido do registro.","aplicacao_pratica":"Sustenta os embargos de terceiro do promitente comprador que não registrou o compromisso, quando o imóvel é atingido por constrição judicial em processo alheio.","precedente_sumula":"Súmula 84, STJ","fundamentacao_legal":"CPC, art. 674 (CPC/1973, art. 1.046, § 1º)"}]$$::jsonb,
array['embargos de terceiro','compromisso de compra e venda','posse'],'vigente','[]'::jsonb,'manual',false),
('Cível','Fraude à execução: registro da penhora ou prova de má-fé do terceiro adquirente','súmula','STJ, DJe 30/03/2009','Súmula 375/STJ','',
$$[{"tese_assunto":"Fraude à execução e boa-fé do terceiro adquirente","ratio_decidendi":"O reconhecimento da fraude à execução depende do registro da penhora do bem alienado ou da prova de má-fé do terceiro adquirente.","aplicacao_pratica":"Em embargos de terceiro ou impugnação à alegação de fraude, exige-se do credor o registro da penhora ou a prova da má-fé do adquirente, sob pena de preservar-se a alienação.","precedente_sumula":"Súmula 375, STJ","fundamentacao_legal":"CPC, art. 792"}]$$::jsonb,
array['fraude à execução','penhora','terceiro adquirente','embargos de terceiro'],'vigente','[]'::jsonb,'manual',false),
('Cível','Seguro: ação regressiva do segurador contra o causador do dano','súmula','STF, Sessão Plenária de 13/12/1963','Súmula 188/STF','',
$$[{"tese_assunto":"Sub-rogação do segurador","ratio_decidendi":"O segurador tem ação regressiva contra o causador do dano, pelo que efetivamente pagou, até ao limite previsto no contrato de seguro.","aplicacao_pratica":"Fundamenta a ação regressiva da seguradora que indenizou o segurado, limitada ao valor efetivamente pago e ao teto contratado.","precedente_sumula":"Súmula 188, STF","fundamentacao_legal":""}]$$::jsonb,
array['seguro','ação regressiva','sub-rogação'],'vigente','[]'::jsonb,'manual',false),
('Cível','Prazo recursal: intimação na sexta-feira e início da contagem na segunda-feira','súmula','STF, Sessão Plenária de 13/12/1963','Súmula 310/STF','',
$$[{"tese_assunto":"Termo inicial do prazo quando a intimação ocorre na sexta-feira","ratio_decidendi":"Quando a intimação tiver lugar na sexta-feira, o prazo judicial terá início na segunda-feira imediata, salvo se não houver expediente, caso em que começará no primeiro dia útil que se seguir.","aplicacao_pratica":"Útil para conferir o termo inicial de prazo em intimação feita em sexta-feira; verificar a regra de contagem do CPC em vigor (art. 224) antes de invocar a súmula.","precedente_sumula":"Súmula 310, STF","fundamentacao_legal":"CPC, art. 224"}]$$::jsonb,
array['prazo','intimação','contagem de prazo'],'vigente','[]'::jsonb,'manual',false),
('Cível','Juizados Especiais: tutela acautelatória e antecipatória','jurisprudência','FONAJE, Enunciado 26 (nova redação, XXIV Encontro, Florianópolis/SC)','Enunciado 26/FONAJE','',
$$[{"tese_assunto":"Tutelas provisórias nos Juizados Especiais Cíveis","ratio_decidendi":"São cabíveis a tutela acautelatória e a antecipatória nos Juizados Especiais Cíveis.","aplicacao_pratica":"Respalda o pedido de tutela provisória em ações de rito dos Juizados Especiais Cíveis.","precedente_sumula":"Enunciado 26, FONAJE","fundamentacao_legal":"Lei 9.099/1995"}]$$::jsonb,
