('Consumidor','Repetição em dobro (CDC, art. 42, parágrafo único): dispensa do elemento volitivo','jurisprudência','STJ, Corte Especial, julgado em 21/10/2020, DJe 30/03/2021','EAREsp 676.608/RS, Corte Especial, Rel. Min. Og Fernandes, j. 21/10/2020, DJe 30/03/2021','',
$$[{"tese_assunto":"Repetição do indébito em dobro independe de dolo ou má-fé","ratio_decidendi":"A repetição em dobro do indébito de cobrança indevida de consumo independe da natureza do elemento volitivo do fornecedor, bastando que a conduta contrarie a boa-fé objetiva.","aplicacao_pratica":"Fundamenta o pedido de devolução em dobro sem necessidade de provar dolo. O Tema 929/STJ, julgado em 15/09/2026, tratou do tema como repetitivo e da modulação: conferir o acórdão publicado antes de citar a modulação.","precedente_sumula":"EAREsp 676.608/RS","fundamentacao_legal":"CDC, art. 42, parágrafo único"}]$$::jsonb,
array['repetição do indébito','cobrança indevida','boa-fé objetiva','tema 929'],'vigente','[]'::jsonb,'manual',false),
('Consumidor','Repetição em dobro: contrariedade à boa-fé objetiva, embargos de declaração nos embargos de divergência','jurisprudência','STJ, Corte Especial, EDcl nos EDiv julgados em 16/03/2022, DJe 27/06/2022','EAREsp 600.663/RS, Corte Especial, Rel. Min. Herman Benjamin','',
$$[{"tese_assunto":"Repetição em dobro e boa-fé objetiva","ratio_decidendi":"Reafirma a orientação da Corte Especial de que a repetição em dobro do indébito consumerista dispensa o elemento volitivo, bastando a contrariedade à boa-fé objetiva.","aplicacao_pratica":"Precedente de reforço, citado com o EAREsp 676.608/RS, em pedidos de repetição em dobro contra fornecedores.","precedente_sumula":"EAREsp 600.663/RS","fundamentacao_legal":"CDC, art. 42, parágrafo único"}]$$::jsonb,
array['repetição do indébito','boa-fé objetiva','tema 929'],'vigente','[]'::jsonb,'manual',false),
('Consumidor','Repetição em dobro: reiteração da tese pela Corte Especial','jurisprudência','STJ, Corte Especial, julgado em 21/02/2024 (Informativo 803)','EAREsp 1.501.756/SC, Corte Especial, Rel. Min. Herman Benjamin, j. 21/02/2024','',
$$[{"tese_assunto":"Repetição em dobro e boa-fé objetiva","ratio_decidendi":"A Corte Especial reiterou a tese de que a repetição em dobro do indébito independe do elemento volitivo, bastando a contrariedade à boa-fé objetiva.","aplicacao_pratica":"Precedente recente para sustentar a devolução em dobro, ao lado do EAREsp 676.608/RS; conferir o Tema 929/STJ (julgado em 15/09/2026).","precedente_sumula":"EAREsp 1.501.756/SC","fundamentacao_legal":"CDC, art. 42, parágrafo único"}]$$::jsonb,
array['repetição do indébito','boa-fé objetiva','tema 929'],'vigente','[]'::jsonb,'manual',false),
('Família','Regime de bens: proventos do trabalho e bens adquiridos com eles (CC, art. 1.659, VI)','jurisprudência','STJ, Terceira Turma, julgado em 21/11/2023, DJe 28/11/2023','REsp 2.106.053/RJ, 3ª Turma, Rel. Min. Marco Aurélio Bellizze, j. 21/11/2023, DJe 28/11/2023','',
$$[{"tese_assunto":"Incomunicabilidade dos proventos e comunicabilidade dos bens adquiridos com eles","ratio_decidendi":"O art. 1.659, VI, do CC protege apenas o direito de receber os proventos do trabalho; os bens adquiridos com esses valores são comunicáveis, presumindo-se que a aquisição onerosa decorre do esforço comum.","aplicacao_pratica":"Sustenta a partilha de bens adquiridos durante a união com proventos de um dos cônjuges ou companheiros, no regime da comunhão parcial.","precedente_sumula":"REsp 2.106.053/RJ","fundamentacao_legal":"CC, art. 1.659, VI"}]$$::jsonb,
array['comunhão parcial','proventos do trabalho','partilha de bens','esforço comum'],'vigente','[]'::jsonb,'manual',false),
('Família','Alimentos a tempo certo ao alimentando apto ao mercado de trabalho','jurisprudência','STJ, Terceira Turma, julgado em 24/08/2010, DJe 01/09/2010','REsp 1.025.769/MG, 3ª Turma, Rel. Min.ª Nancy Andrighi, j. 24/08/2010, DJe 01/09/2010','',
$$[{"tese_assunto":"Alimentos fixados por prazo certo","ratio_decidendi":"Admitem-se alimentos a tempo certo quando o alimentando tem idade, condições e formação para ingressar no mercado de trabalho.","aplicacao_pratica":"Fundamento para pedir a fixação de alimentos temporários, ou sua exoneração ao fim do prazo, quando o alimentando é apto ao trabalho.","precedente_sumula":"REsp 1.025.769/MG","fundamentacao_legal":"CC, arts. 1.694 e 1.695"}]$$::jsonb,
array['alimentos','alimentos transitórios','mercado de trabalho'],'vigente','[]'::jsonb,'manual',false),
('Cível','Valor da causa nos embargos de terceiro','jurisprudência','STJ, Terceira Turma, julgado em 06/03/2018, DJe 12/03/2018','REsp 1.689.175/MS, 3ª Turma, Rel. Min. Ricardo Villas Bôas Cueva, j. 06/03/2018, DJe 12/03/2018','',
$$[{"tese_assunto":"Valor da causa nos embargos de terceiro","ratio_decidendi":"O valor da causa nos embargos de terceiro corresponde ao valor do bem penhorado.","aplicacao_pratica":"Orienta a atribuição do valor da causa na petição dos embargos de terceiro, evitando impugnação.","precedente_sumula":"REsp 1.689.175/MS","fundamentacao_legal":"CPC, art. 292"}]$$::jsonb,
array['embargos de terceiro','valor da causa'],'vigente','[]'::jsonb,'manual',false),
('Família','Salário mínimo como base de cálculo da pensão alimentícia','jurisprudência','STF, Plenário (Plenário Virtual), repercussão geral reconhecida em 05/06/2015','ARE 842.157/DF, Tema 821/STF, Rel. Min. Dias Toffoli','',
$$[{"tese_assunto":"Pensão alimentícia fixada em salários mínimos","ratio_decidendi":"A utilização do salário mínimo como base de cálculo do valor de pensão alimentícia não viola a Constituição Federal.","aplicacao_pratica":"Afasta a alegação de inconstitucionalidade da fixação dos alimentos em número de salários mínimos (CF, art. 7º, IV).","precedente_sumula":"Tema 821, STF","fundamentacao_legal":"CF, art. 7º, IV"}]$$::jsonb,
array['alimentos','pensão alimentícia','salário mínimo','repercussão geral'],'vigente','[]'::jsonb,'manual',false),
