$$[{"tese_assunto":"Fraude de execução e registro da penhora","ratio_decidendi":"O reconhecimento da fraude de execução depende do registro da penhora do bem alienado (tese 1.2 do Tema 243).","aplicacao_pratica":"Em conjunto com a Súmula 375/STJ, orienta a defesa do terceiro adquirente e a prova exigida do credor.","precedente_sumula":"Tema 243, STJ","fundamentacao_legal":"CPC, art. 792"}]$$::jsonb,
