('Penal','Livramento condicional: requisito subjetivo e histórico prisional','jurisprudência','STJ, Terceira Seção, julgado em 24/05/2023','Tema 1.161/STJ, REsp 1.970.217/MG e REsp 1.974.104/RS, 3ª Seção, Rel. Min. Ribeiro Dantas, j. 24/05/2023','',
$$[{"tese_assunto":"Livramento condicional e histórico prisional","ratio_decidendi":"O requisito subjetivo do livramento condicional deve considerar todo o histórico prisional, não se limitando ao período de 12 meses.","aplicacao_pratica":"Orienta a análise do mérito do apenado no pedido de livramento condicional, tanto para o requerimento quanto para a defesa contra o indeferimento.","precedente_sumula":"Tema 1.161, STJ","fundamentacao_legal":"CP, art. 83; LEP, art. 131"}]$$::jsonb,
array['livramento condicional','execução penal','recurso repetitivo'],'vigente','[]'::jsonb,'manual',false),
('Penal','Revisão criminal: justificação criminal como via para a prova nova','jurisprudência','STJ, Sexta Turma, julgado em 25/08/2015, DJe 15/09/2015 (Informativo 569)','RHC 58.442, 6ª Turma, Rel. Min. Sebastião Reis Júnior, j. 25/08/2015, DJe 15/09/2015','',
$$[{"tese_assunto":"Prova nova e justificação criminal","ratio_decidendi":"A justificação criminal é a via adequada para a produção de prova nova que subsidie a revisão criminal; a declaração unilateral feita em cartório não serve a esse fim.","aplicacao_pratica":"Antes de ajuizar a revisão criminal com base em testemunhas ou documentos novos, requerer a justificação criminal em vez de juntar declaração notarial unilateral.","precedente_sumula":"RHC 58.442","fundamentacao_legal":"CPP, art. 621, III"}]$$::jsonb,
array['revisão criminal','justificação criminal','prova nova'],'vigente','[]'::jsonb,'manual',false),
('Penal','Revisão criminal: retratação de testemunha como prova nova','jurisprudência','STJ, Quinta Turma, DJe 29/08/2011','HC 140.618, 5ª Turma, Rel. Min. Jorge Mussi, DJe 29/08/2011','',
$$[{"tese_assunto":"Retratação de testemunha e prova nova","ratio_decidendi":"A retratação de testemunha pode constituir prova nova para a revisão criminal, desde que submetida à justificação.","aplicacao_pratica":"Fundamento para a revisão criminal fundada em retratação de testemunha, precedida de justificação criminal.","precedente_sumula":"HC 140.618","fundamentacao_legal":"CPP, art. 621, III"}]$$::jsonb,
array['revisão criminal','prova nova','retratação de testemunha'],'vigente','[]'::jsonb,'manual',false),
('Penal','Revisão criminal: ausência de efeito suspensivo','jurisprudência','STJ, Sexta Turma, DJe 06/09/2010 (Informativo 443)','HC 169.605, 6ª Turma, Rel. Min. Og Fernandes, DJe 06/09/2010','',
$$[{"tese_assunto":"Efeito suspensivo da revisão criminal","ratio_decidendi":"A revisão criminal não tem efeito suspensivo.","aplicacao_pratica":"O ajuizamento da revisão criminal não suspende a execução da pena; eventual suspensão exige pedido de tutela específico.","precedente_sumula":"HC 169.605","fundamentacao_legal":"CPP, arts. 621 a 631"}]$$::jsonb,
array['revisão criminal','efeito suspensivo'],'vigente','[]'::jsonb,'manual',false),
('Penal','Revisão criminal: justificação criminal e prova nova (Jurisprudência em Teses, ed. 63, tese 15)','jurisprudência','STJ, Jurisprudência em Teses, edição 63 (Revisão Criminal), tese 15','STJ, Jurisprudência em Teses, ed. 63 (Revisão Criminal), tese 15','',
$$[{"tese_assunto":"Justificação criminal","ratio_decidendi":"A justificação criminal é via adequada à obtenção de prova nova para subsidiar eventual ajuizamento de revisão criminal.","aplicacao_pratica":"Apoia o requerimento de justificação criminal prévia à revisão criminal.","precedente_sumula":"Jurisprudência em Teses, ed. 63, tese 15","fundamentacao_legal":"CPP, art. 621, III"}]$$::jsonb,
array['revisão criminal','justificação criminal','jurisprudência em teses'],'vigente','[]'::jsonb,'manual',false),
('Penal','Revisão criminal: novas testemunhas não fundamentam o pedido (Jurisprudência em Teses, ed. 63, tese 16)','jurisprudência','STJ, Jurisprudência em Teses, edição 63 (Revisão Criminal), tese 16','STJ, Jurisprudência em Teses, ed. 63 (Revisão Criminal), tese 16','',
$$[{"tese_assunto":"Revisão criminal e rol de novas testemunhas","ratio_decidendi":"A revisão criminal não pode ser fundamentada no arrolamento de novas testemunhas.","aplicacao_pratica":"Impede a revisão criminal que apenas arrola testemunhas novas; a prova nova deve ser demonstrada de outra forma, como documento ou justificação.","precedente_sumula":"Jurisprudência em Teses, ed. 63, tese 16","fundamentacao_legal":"CPP, art. 621, III"}]$$::jsonb,
array['revisão criminal','prova testemunhal','jurisprudência em teses'],'vigente','[]'::jsonb,'manual',false);
